/* 로컬(내 컴퓨터) 환경에서는 window.storage가 없으므로 localStorage로 자동 대체 */
const storageGet = async (key) => {
  if (typeof window !== 'undefined' && window.storage) {
    try { return await window.storage.get(key, false); } catch (e) { return null; }
  }
  const v = typeof window !== 'undefined' ? window.localStorage.getItem(key) : null;
  return v ? { value: v } : null;
};
const storageSet = async (key, value) => {
  if (typeof window !== 'undefined' && window.storage) return window.storage.set(key, value, false);
  window.localStorage.setItem(key, value);
};
const storageDelete = async (key) => {
  if (typeof window !== 'undefined' && window.storage) return window.storage.delete(key, undefined);
  window.localStorage.removeItem(key);
};
const prefersDark = () => typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;

